// =============================================================================
// Auto-generated by verify/emit_tb_ntt.py -- do not edit by hand.
// Testbench for rtl/core/kyber_ntt.v against the golden vectors in
// verify/ntt_golden.mem (produced from results/ntt_golden.json, whose
// model is cross-checked by the ring-homomorphism oracle).
//
// Run from the project root:
//   iverilog -g2012 -o tb.vvp verify/tb_kyber_ntt.v rtl/core/kyber_ntt.v
//   vvp tb.vvp
// ($readmemh resolves the path relative to the invocation directory;
//  the bench therefore references verify/ntt_golden.mem directly.)
// =============================================================================

`timescale 1ns / 1ps

module tb_kyber_ntt;

    // ----------------------------------------------------------------
    // golden vectors: flat 5120-entry memory, one 16-bit coeff per entry.
    // Layout: [X_*, NTT_*, INTT_*] in tag order RAND,ZERO,POS,NEG,EXT.
    // ----------------------------------------------------------------
    reg [15:0] GOLD [0:5119];
    localparam integer X_BASE     =    0;  // 256, 512, 768, 1024
    localparam integer NTT_BASE   = 1280;  // 1536, 1792, 2048, 2304
    localparam integer INTT_BASE  = 2560;  // 2816, 3072, 3328, 3584
    localparam integer RT_BASE    = 3840;  // 4096, 4352, 4608, 4864

    initial $readmemh("verify/ntt_golden.mem", GOLD);

    // ----------------------------------------------------------------
    // clock / reset
    // ----------------------------------------------------------------
    reg clk = 0;
    reg rst_n = 0;

    always #5 clk = ~clk;

    // ----------------------------------------------------------------
    // DUT signals
    // ----------------------------------------------------------------
    reg                start = 0;
    reg                inverse = 0;
    wire               busy;
    wire               done;

    reg                load = 0;
    reg  [7:0]         load_addr = 0;
    reg  [15:0]        load_data = 0;

    reg  [7:0]         read_addr = 0;
    wire [15:0]        read_data;

    // ----------------------------------------------------------------
    // DUT
    // ----------------------------------------------------------------
    kyber_ntt #(.N(256), .Q(3329), .BW(16)) dut (
        .clk        (clk),
        .rst_n      (rst_n),
        .start      (start),
        .inverse    (inverse),
        .busy       (busy),
        .done       (done),
        .load       (load),
        .load_addr  (load_addr),
        .load_data  (load_data),
        .read_addr  (read_addr),
        .read_data  (read_data)
    );

    // ----------------------------------------------------------------
    // watchdog -- generous: 15 tests x (256 load + ~4000 pipelined
    // transform ticks + 256 read).  The 3-tick butterfly pipeline is
    // ~3x slower than the original single-cycle DUT, so this must
    // cover ~60k cycles = 600 us; 5 ms leaves ample headroom.
    // ----------------------------------------------------------------
    initial begin
        #5000000;
        $display("FATAL: watchdog fired at %t", $time);
        $finish;
    end

    // ----------------------------------------------------------------
    // counters and shared state
    // ----------------------------------------------------------------
    integer n_pass = 0;
    integer n_fail = 0;
    integer i;
    integer nbad;
    integer first;
    reg [15:0] R;

    // ----------------------------------------------------------------
    // helpers
    // ----------------------------------------------------------------
    task reset_dut;
        begin
            start = 0; load = 0; inverse = 0;
            load_addr = 0; load_data = 0; read_addr = 0;
            rst_n = 0;
            repeat (4) @(posedge clk);
            rst_n = 1;
            @(posedge clk);
        end
    endtask

    // Stream 256 coefficients in, coeff 0 first.
    //
    // RACE-FIX (the 1-pass/9-fail bug): load/load_addr/load_data MUST be
    // driven off negedge clk.  When they were plain blocking assignments
    // in a loop that then did `@(posedge clk)`, the first iteration's
    // assignments could land in the SAME simulation-time step as the very
    // posedge they were meant to precede.  iverilog then sometimes ran the
    // bench's continuation (already setting iteration i+1's load_addr)
    // BEFORE the DUT's always block sampled its inputs at that posedge --
    // so the DUT wrote coeff[1] when the bench meant coeff[0], silently
    // losing exactly one coefficient per load phase.  The loss only bit
    // when the load was preceded by a #1-terminated read-back phase
    // (check_result), which is why test 0 (fresh from reset) passed and
    // tests 1-9 failed.  With every input changing at negedge and the
    // write happening at the following posedge, there is a 5 ns setup
    // margin and no scheduling-order dependency can exist.
    task load_vec;
        input integer base;
        begin
            @(negedge clk);
            load = 1;
            for (i = 0; i < 256; i = i + 1) begin
                load_addr = i[7:0];
                load_data = GOLD[base + i];
                @(posedge clk);      // DUT samples addr=i, data=GOLD[base+i]
                @(negedge clk);      // safe point for the next address
            end
            load = 0;
        end
    endtask

    // Pulse start for exactly one sampled clock, driven off negedge so
    // the DUT cannot miss it through a posedge-time race.
    task pulse_start;
        begin
            @(negedge clk);
            start = 1;
            @(posedge clk);
            @(negedge clk);
            start = 0;
        end
    endtask

    task wait_done;
        begin
            wait (done === 1'b1);
            @(posedge clk);
        end
    endtask

    // Read the result back coefficient by coefficient and compare
    // against the golden half of the same pair.  read_addr is driven off
    // negedge so the combinational read port has a full half-cycle to
    // settle before the sample; #1 is kept as a delta-settle guard.
    task check_result;
        input integer exp_base;
        begin
            nbad  = 0;
            first = -1;
            @(negedge clk);
            for (i = 0; i < 256; i = i + 1) begin
                read_addr = i[7:0];
                #1;
                R = read_data;
                if (R !== GOLD[exp_base + i]) begin
                    nbad = nbad + 1;
                    if (first < 0) first = i;
                end
            end
        end
    endtask

    task run_fwd;
        input integer in_base;
        input integer exp_base;
        input integer tnum;
        begin
            inverse = 1'b0;
            load_vec(in_base);
            pulse_start;
            wait_done;
            check_result(exp_base);
            if (nbad == 0) begin
                n_pass = n_pass + 1;
                $display("PASS  forward NTT  test %0d", tnum);
            end else begin
                n_fail = n_fail + 1;
                $display("FAIL  forward NTT  test %0d : %0d/256 differ, first %0d",
                         tnum, nbad, first);
            end
        end
    endtask

    task run_inv;
        input integer in_base;
        input integer exp_base;
        input integer tnum;
        begin
            inverse = 1'b1;
            load_vec(in_base);
            pulse_start;
            wait_done;
            check_result(exp_base);
            if (nbad == 0) begin
                n_pass = n_pass + 1;
                $display("PASS  inverse INTT test %0d", tnum);
            end else begin
                n_fail = n_fail + 1;
                $display("FAIL  inverse INTT test %0d : %0d/256 differ, first %0d",
                         tnum, nbad, first);
            end
        end
    endtask

    // ----------------------------------------------------------------
    // main
    // ----------------------------------------------------------------
    initial begin
        $dumpfile("tb_kyber_ntt.vcd");
        $dumpvars(0, tb_kyber_ntt);

        reset_dut;
        $display("--- kyber_ntt KAT: q=3329, N=256, R mod q=2285 ---", 2285);

        // X_RAND -> NTT_RAND
        run_fwd(X_BASE + 0, NTT_BASE + 0, 0);
        // X_ZERO -> NTT_ZERO
        run_fwd(X_BASE + 256, NTT_BASE + 256, 1);
        // X_POS -> NTT_POS
        run_fwd(X_BASE + 512, NTT_BASE + 512, 2);
        // X_NEG -> NTT_NEG
        run_fwd(X_BASE + 768, NTT_BASE + 768, 3);
        // X_EXT -> NTT_EXT
        run_fwd(X_BASE + 1024, NTT_BASE + 1024, 4);

        // X_RAND -> INTT_RAND  (inverse on the raw polynomial)
        run_inv(X_BASE + 0, INTT_BASE + 0, 5);
        // X_ZERO -> INTT_ZERO  (inverse on the raw polynomial)
        run_inv(X_BASE + 256, INTT_BASE + 256, 6);
        // X_POS -> INTT_POS  (inverse on the raw polynomial)
        run_inv(X_BASE + 512, INTT_BASE + 512, 7);
        // X_NEG -> INTT_NEG  (inverse on the raw polynomial)
        run_inv(X_BASE + 768, INTT_BASE + 768, 8);
        // X_EXT -> INTT_EXT  (inverse on the raw polynomial)
        run_inv(X_BASE + 1024, INTT_BASE + 1024, 9);

        // NTT_RAND -> RT_RAND  (round trip: invntt of ntt(x) = 2285*x)
        run_inv(NTT_BASE + 0, RT_BASE + 0, 10);
        // NTT_ZERO -> RT_ZERO  (round trip: invntt of ntt(x) = 2285*x)
        run_inv(NTT_BASE + 256, RT_BASE + 256, 11);
        // NTT_POS -> RT_POS  (round trip: invntt of ntt(x) = 2285*x)
        run_inv(NTT_BASE + 512, RT_BASE + 512, 12);
        // NTT_NEG -> RT_NEG  (round trip: invntt of ntt(x) = 2285*x)
        run_inv(NTT_BASE + 768, RT_BASE + 768, 13);
        // NTT_EXT -> RT_EXT  (round trip: invntt of ntt(x) = 2285*x)
        run_inv(NTT_BASE + 1024, RT_BASE + 1024, 14);

        $display("---------------------------------------------");
        $display("RESULT: %0d passed, %0d failed", n_pass, n_fail);
        if (n_fail == 0)
            $display("ALL TESTS PASSED");
        else
            $display("TESTS FAILED");
        $finish;
    end

endmodule
